package com.galesong.tithecoach;

import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.RuneLite;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

final class DebugRunLogger implements AutoCloseable {
  private static final Logger LOG = LoggerFactory.getLogger(DebugRunLogger.class);
  private static final String HEADER =
      "timestamp,elapsed_seconds,event,method,phase,expected_kind,expected_route_index,"
          + "actual_route_index,transition,out_of_order,harvested_total,inventory_fruit,"
          + "reward_points,session_points_earned,current_set_points,permanent_shop_progress,"
          + "sets_to_buyout,water_doses,water_needed,gricollers_can,active_plants,dry,"
          + "watered,grown,dead,instruction";

  private final TitheFarmCoachPlugin plugin;
  private final Map<WorldPoint, PlantState> previousStates = new HashMap<>();
  private BufferedWriter writer;
  private Instant started;
  private Instant lastSnapshot = Instant.EPOCH;
  private String lastStepKey = "";

  DebugRunLogger(TitheFarmCoachPlugin plugin) {
    this.plugin = plugin;
  }

  void tick() {
    if (!plugin.isInTitheFarm()) {
      close();
      previousStates.clear();
      return;
    }

    ensureStarted();
    recordTransitions();

    CoachStep step = plugin.getStep();
    String stepKey = step.kind + ":" + (step.target == null ? "" : step.target.toString());
    if (!stepKey.equals(lastStepKey)) {
      lastStepKey = stepKey;
      write("INSTRUCTION_CHANGE", "", -1, false);
    }

    Instant now = Instant.now();
    if (Duration.between(lastSnapshot, now).getSeconds() >= 5) {
      lastSnapshot = now;
      write("SNAPSHOT", "", -1, false);
    }
  }

  private void ensureStarted() {
    if (writer != null) {
      return;
    }

    try {
      Path directory = RuneLite.RUNELITE_DIR.toPath().resolve("tithe-farm-coach-runs");
      Files.createDirectories(directory);
      started = Instant.now();
      String stamp =
          DateTimeFormatter.ofPattern("yyyy-MM-dd_HH-mm-ss")
              .withZone(ZoneId.systemDefault())
              .format(started);
      Path file = directory.resolve("tithe-coach-" + stamp + ".csv");
      writer =
          Files.newBufferedWriter(
              file,
              StandardCharsets.UTF_8,
              StandardOpenOption.CREATE_NEW,
              StandardOpenOption.WRITE);
      writer.write(HEADER);
      writer.newLine();
      write("SESSION_START", "", -1, false);
    } catch (IOException ex) {
      LOG.warn("Unable to open debug run log", ex);
      close();
    }
  }

  private void recordTransitions() {
    for (Map.Entry<WorldPoint, TithePlot> entry : plugin.getPlots().entrySet()) {
      WorldPoint point = entry.getKey();
      PlantState next = entry.getValue().state;
      PlantState previous = previousStates.put(point, next);
      if (previous == null || previous == next) {
        continue;
      }

      String action = observedAction(previous, next);
      if (action == null) {
        continue;
      }

      int actual = plugin.getRoute().indexOf(point);
      int expected = plugin.expectedRouteIndex();
      boolean orderSensitive =
          action.equals("PLANT") || action.equals("WATER") || action.equals("HARVEST");
      boolean outOfOrder = orderSensitive && actual >= 0 && expected >= 0 && actual != expected;
      write(
          outOfOrder ? "OUT_OF_ORDER" : "OBSERVED_ACTION",
          action + ":" + previous + "->" + next,
          actual,
          outOfOrder);
    }
  }

  private String observedAction(PlantState previous, PlantState next) {
    if (previous == PlantState.EMPTY && (next == PlantState.DRY || next == PlantState.WATERED)) {
      return "PLANT";
    }
    if (previous == PlantState.DRY && next == PlantState.WATERED) {
      return "WATER";
    }
    if (previous == PlantState.GROWN && next == PlantState.EMPTY) {
      return "HARVEST";
    }
    if (previous == PlantState.DEAD && next == PlantState.EMPTY) {
      return "CLEAR_DEAD";
    }
    if (previous != PlantState.DEAD && next == PlantState.DEAD) {
      return "PLANT_DIED";
    }
    return null;
  }

  private void write(String event, String transition, int actual, boolean outOfOrder) {
    if (writer == null) {
      return;
    }

    try {
      CoachStep step = plugin.getStep();
      int dry = 0;
      int watered = 0;
      int grown = 0;
      int dead = 0;
      int active = 0;
      for (WorldPoint point : plugin.getRoute()) {
        TithePlot plot = plugin.getPlots().get(point);
        if (plot == null) {
          continue;
        }
        if (plot.state != PlantState.EMPTY) {
          active++;
        }
        if (plot.state == PlantState.DRY) {
          dry++;
        } else if (plot.state == PlantState.WATERED) {
          watered++;
        } else if (plot.state == PlantState.GROWN) {
          grown++;
        } else if (plot.state == PlantState.DEAD) {
          dead++;
        }
      }

      String[] values = {
        Instant.now().toString(),
        String.valueOf(Duration.between(started, Instant.now()).getSeconds()),
        event,
        plugin.methodName(),
        plugin.phaseName(),
        step.kind.name(),
        String.valueOf(plugin.expectedRouteIndex()),
        String.valueOf(actual),
        transition,
        String.valueOf(outOfOrder),
        String.valueOf(plugin.getHarvestedTotal()),
        String.valueOf(plugin.inventoryFruitCount()),
        String.valueOf(plugin.getRewardPoints()),
        String.valueOf(plugin.getSessionPointsEarned()),
        String.valueOf(plugin.getCurrentSetPointsEarned()),
        String.valueOf(plugin.getPermanentShopProgress()),
        String.valueOf(plugin.getFullSetsToPermanentBuyout()),
        String.valueOf(plugin.getWaterDoseCount()),
        String.valueOf(plugin.getRemainingWaterNeeded()),
        String.valueOf(plugin.isUsingGricollersCan()),
        String.valueOf(active),
        String.valueOf(dry),
        String.valueOf(watered),
        String.valueOf(grown),
        String.valueOf(dead),
        step.title + ". " + step.detail
      };

      for (int index = 0; index < values.length; index++) {
        if (index > 0) {
          writer.write(',');
        }
        writer.write(csv(values[index]));
      }
      writer.newLine();
      writer.flush();
    } catch (IOException ex) {
      LOG.warn("Unable to write debug run log", ex);
      close();
    }
  }

  private String csv(String value) {
    return "\"" + (value == null ? "" : value.replace("\"", "\"\"")) + "\"";
  }

  @Override
  public void close() {
    if (writer == null) {
      return;
    }
    try {
      writer.close();
    } catch (IOException ex) {
      LOG.debug("Unable to close debug run log", ex);
    } finally {
      writer = null;
      lastStepKey = "";
      lastSnapshot = Instant.EPOCH;
    }
  }
}

package com.galesong.tithecoach;

import com.google.inject.Inject;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;

@PluginDescriptor(
    name = "Tithe Farm Coach (Debug)",
    description = "Development build of Tithe Farm Coach with local run logging",
    tags = {"tithe", "farm", "debug"})
public class TitheFarmCoachDebugPlugin extends Plugin {
  @Inject private PluginManager pluginManager;

  private DebugRunLogger runLogger;

  @Override
  protected void startUp() {
    TitheFarmCoachPlugin coach =
        pluginManager.getPlugins().stream()
            .filter(TitheFarmCoachPlugin.class::isInstance)
            .map(TitheFarmCoachPlugin.class::cast)
            .findFirst()
            .orElse(null);
    if (coach != null) {
      runLogger = new DebugRunLogger(coach);
    }
  }

  @Override
  protected void shutDown() {
    if (runLogger != null) {
      runLogger.close();
      runLogger = null;
    }
  }

  @Subscribe
  public void onGameTick(GameTick event) {
    if (runLogger != null) {
      runLogger.tick();
    }
  }
}

package com.galesong.tithecoach;

import static org.junit.Assert.*;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class TitheRoutesTest {
  private final List<WorldPoint> guides = new ArrayList<>();
  private final Map<WorldPoint, TithePlot> plots = new LinkedHashMap<>();

  public TitheRoutesTest() {
    for (int i = 0; i < 25; i++) {
      WorldPoint point = new WorldPoint(1000 + 5 * i, 2000, 0);
      guides.add(point);
      plots.put(point, new TithePlot(point, null, PlantState.EMPTY));
    }
  }

  @Test
  public void everyMethodHasEnoughMarkersAndPracticeMethodsShareTheStandardRoute() {
    for (TitheMethod method : TitheMethod.values()) {
      assertTrue(TitheRoutes.officialRoute(method).length >= method.plants);
    }
    assertArrayEquals(
        TitheRoutes.officialRoute(TitheMethod.STANDARD_20),
        TitheRoutes.officialRoute(TitheMethod.RELAXED_8));
    assertArrayEquals(
        TitheRoutes.officialRoute(TitheMethod.STANDARD_20),
        TitheRoutes.officialRoute(TitheMethod.SAFE_16));
  }

  @Test
  public void usesMethodSizeAndShortensTheFinalBatch() {
    for (TitheMethod method : TitheMethod.values()) {
      assertEquals(guides.subList(0, method.plants), build(method, 0));
      assertEquals(guides.subList(0, 4), build(method, 96));
    }
  }

  @Test
  public void retainsLivePlantsButExcludesDeadPlantsWhenRebuilding() {
    plots.get(guides.get(0)).state = PlantState.WATERED;
    plots.get(guides.get(1)).state = PlantState.DEAD;
    List<WorldPoint> route = build(TitheMethod.RELAXED_8, 0);
    assertEquals(guides.get(0), route.get(0));
    assertFalse(route.contains(guides.get(1)));
    assertEquals(8, route.size());
    assertEquals(8, new java.util.HashSet<>(route).size());
  }

  private List<WorldPoint> build(TitheMethod method, int harvested) {
    return TitheRoutes.build(method, plots, harvested, guides);
  }
}

package com.galesong.tithecoach;

import static org.junit.Assert.*;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Item;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class CoachEngineTest {
  private final CoachEngine coach = new CoachEngine();
  private final List<WorldPoint> patches = new ArrayList<>();
  private final Instant now = Instant.parse("2026-01-01T00:00:00Z");

  public CoachEngineTest() {
    coach.changeMethod(TitheMethod.RELAXED_8);
    supplies(1000, 0);
    for (int i = 0; i < 8; i++) {
      WorldPoint point = new WorldPoint(1000 + i, 2000, 0);
      patches.add(point);
      coach.updatePlot(point, null, PlantState.EMPTY, now);
    }
    coach.route.addAll(patches);
  }

  @Test
  public void preparationChecksToolsSeedsAndWaterInOrder() {
    List<Item> items = new ArrayList<>();
    String[] expected = {
      "GET A SPADE", "GET A SEED DIBBER", "TAKE TITHE SEEDS", "FILL WATERING CANS"
    };
    int[] supplies = {
      ItemID.SPADE, ItemID.DIBBER, ItemID.HOSIDIUS_TITHE_SEED_A, ItemID.ZEAH_WATERINGCAN
    };
    for (int i = 0; i < supplies.length; i++) {
      coach.inventory = new TitheInventory(items.toArray(new Item[0]), 24);
      assertEquals(expected[i], coach.preparationStep().title);
      items.add(new Item(supplies[i], 1));
    }
    coach.inventory = new TitheInventory(items.toArray(new Item[0]), 24);
    assertEquals("ENTER TITHE FARM", coach.preparationStep().title);
  }

  @Test
  public void plantsThenWatersBeforeAdvancingAndQueuesTheNextPatch() {
    expect(CoachStep.Kind.PLANT, 0);
    change(0, PlantState.DRY);
    expect(CoachStep.Kind.WATER, 0);
    assertEquals(patches.get(1), coach.getQueuedPlantTarget());
    assertFalse(coach.isQueuedPlantClickReady());
    change(0, PlantState.WATERED);
    assertTrue(coach.isQueuedPlantClickReady());
    assertEquals(23, coach.getRemainingWaterNeeded());
    expect(CoachStep.Kind.PLANT, 1);
    assertNull(coach.getQueuedPlantTarget());
  }

  @Test
  public void finishesNewPlantPairBeforeReturningToOlderDryPlants() {
    change(0, PlantState.DRY);
    change(0, PlantState.WATERED);
    change(0, PlantState.DRY);
    expect(CoachStep.Kind.PLANT, 1);
    change(1, PlantState.DRY);
    expect(CoachStep.Kind.WATER, 1);
  }

  @Test
  public void wateringCircuitMovesForwardThenWrapsWithoutBacktracking() {
    plantBatch();
    expect(CoachStep.Kind.WAIT, 0);
    change(5, PlantState.DRY);
    change(5, PlantState.WATERED);
    change(0, PlantState.DRY);
    change(6, PlantState.DRY);
    expect(CoachStep.Kind.WATER, 6);
    change(6, PlantState.WATERED);
    expect(CoachStep.Kind.WATER, 0);
    change(0, PlantState.WATERED);
    expect(CoachStep.Kind.WAIT, 1);
  }

  @Test
  public void watersBeforeHarvestingButHarvestsRipePlantsBeforeWaiting() {
    plantBatch();
    expect(CoachStep.Kind.WAIT, 0);
    change(0, PlantState.GROWN);
    change(1, PlantState.DRY);
    expect(CoachStep.Kind.WATER, 1);
    change(1, PlantState.WATERED);
    expect(CoachStep.Kind.HARVEST, 0);
    change(0, PlantState.EMPTY);
    assertEquals(1, coach.getHarvestedTotal());
    expect(CoachStep.Kind.WAIT, 1);
  }

  @Test
  public void clearsDeadPlantsOnlyAfterLivingPlantsAreFinished() {
    plantBatch();
    expect(CoachStep.Kind.WAIT, 0);
    change(0, PlantState.DEAD);
    expect(CoachStep.Kind.WAIT, 1);
    for (int i = 1; i < 8; i++) {
      change(i, PlantState.GROWN);
      expect(CoachStep.Kind.HARVEST, i);
      change(i, PlantState.EMPTY);
    }
    expect(CoachStep.Kind.RECOVER, 0);
    change(0, PlantState.EMPTY);
    supplies(0, 7);
    expect(CoachStep.Kind.DEPOSIT, -1);
    assertEquals(7, coach.getHarvestedTotal());
  }

  @Test
  public void rejectsInsufficientStartingWaterAndRefillsDuringAnActiveBatch() {
    supplies(23, 0);
    expect(CoachStep.Kind.PREPARE, -1);
    assertTrue(coach.isBatchBlockedByWater(coach.inventory.waterDoseCount()));
    supplies(24, 0);
    expect(CoachStep.Kind.PLANT, 0);
    change(0, PlantState.DRY);
    supplies(0, 0);
    coach.waterSource = new WorldPoint(900, 2000, 0);
    assertEquals(coach.waterSource, decide().target);
    assertEquals(CoachStep.Kind.REFILL, coach.step.kind);
    supplies(1, 0);
    expect(CoachStep.Kind.WATER, 0);
  }

  @Test
  public void batchWaterWarningUsesCurrentDosesAndOnlyAppliesBeforeLivePlants() {
    assertTrue(coach.isBatchBlockedByWater(23));
    assertFalse(coach.isBatchBlockedByWater(24));
    expect(CoachStep.Kind.PLANT, 0);
    for (PlantState state : new PlantState[] {PlantState.DRY, PlantState.WATERED, PlantState.GROWN}) {
      change(0, state);
      assertFalse(coach.isBatchBlockedByWater(0));
    }
    change(0, PlantState.DEAD);
    assertTrue(coach.isBatchBlockedByWater(0));
    coach.route.clear();
    assertFalse(coach.isBatchBlockedByWater(0));
  }

  @Test
  public void depositsBeforeRefillingThenStartsTheNextBatch() {
    finishBatch();
    supplies(0, 8);
    coach.depositSack = new WorldPoint(900, 2000, 0);
    assertEquals(CoachStep.Kind.DEPOSIT, decide().kind);
    assertEquals(coach.depositSack, coach.step.target);
    supplies(0, 0);
    assertEquals("REFILL GRICOLLER'S CAN", decide().title);
    supplies(1000, 0);
    assertNull(coach.decide());
    assertTrue(coach.route.isEmpty());
    coach.route.addAll(patches);
    expect(CoachStep.Kind.PLANT, 0);
  }

  @Test
  public void finalPartialBatchStillUsesFullMethodWaterCheckAndRefillsBeforeCompletion() {
    for (int batch = 0; batch < 12; batch++) {
      finishBatch();
      assertNull(coach.decide());
      coach.route.addAll(patches);
    }
    assertEquals(96, coach.getHarvestedTotal());
    coach.route.subList(4, 8).clear();
    supplies(12, 0);
    expect(CoachStep.Kind.PREPARE, -1);
    supplies(24, 0);
    finishBatch();
    assertEquals(100, coach.getHarvestedTotal());
    supplies(0, 4);
    expect(CoachStep.Kind.DEPOSIT, -1);
    supplies(0, 0);
    expect(CoachStep.Kind.REFILL, -1);
    supplies(24, 0);
    expect(CoachStep.Kind.COMPLETE, -1);
  }

  @Test
  public void methodChangeRetainsPlantsAndHarvestCountButRestartsPlanting() {
    plantBatch();
    expect(CoachStep.Kind.WAIT, 0);
    change(0, PlantState.GROWN);
    change(0, PlantState.EMPTY);
    coach.changeMethod(TitheMethod.SAFE_16);
    assertTrue(coach.route.isEmpty());
    assertEquals(1, coach.getHarvestedTotal());
    assertEquals(PlantState.WATERED, coach.plots.get(patches.get(1)).state);
    coach.route.addAll(patches);
    expect(CoachStep.Kind.PLANT, 0);
    assertEquals(48, coach.requiredWaterDoses());
  }

  @Test
  public void resetClearsRunButPreservesLaunchRewardEarnings() {
    coach.updateRewardPoints(100);
    coach.beginSet();
    coach.updateRewardPoints(135);
    finishBatch();
    coach.reset();
    assertTrue(coach.plots.isEmpty());
    assertTrue(coach.route.isEmpty());
    assertEquals(0, coach.getHarvestedTotal());
    assertEquals(35, coach.getSessionPointsEarned());
    coach.beginSet();
    assertEquals(0, coach.getCurrentSetPointsEarned());
  }

  @Test
  public void rewardSpendingDoesNotSubtractEarnedPointsAndBuyoutRoundsUp() {
    coach.updateRewardPoints(100);
    coach.beginSet();
    coach.updateRewardPoints(135);
    coach.updateRewardPoints(85);
    assertEquals(35, coach.getCurrentSetPointsEarned());
    assertEquals(135, coach.getPermanentShopProgress(50));
    assertEquals(29, coach.getFullSetsToPermanentBuyout(50));
    coach.updateRewardPoints(134);
    assertEquals(1, coach.getFullSetsToPermanentBuyout(1000));
    assertEquals(1150, coach.getPermanentShopProgress(1150));
    assertEquals(0, coach.getFullSetsToPermanentBuyout(1150));
  }

  @Test
  public void stageTimingResetsOnDryingButNotWateringAndHarvestsCountOnce() {
    change(0, PlantState.DRY);
    coach.updatePlot(patches.get(0), null, PlantState.WATERED, now.plusSeconds(5));
    assertEquals(now, coach.plots.get(patches.get(0)).stageStarted);
    coach.updatePlot(patches.get(0), null, PlantState.DRY, now.plusSeconds(60));
    assertEquals(now.plusSeconds(60), coach.plots.get(patches.get(0)).stageStarted);
    change(0, PlantState.GROWN);
    change(0, PlantState.EMPTY);
    change(0, PlantState.EMPTY);
    assertEquals(1, coach.getHarvestedTotal());
    assertEquals(0, coach.plots.get(patches.get(0)).wateringCount);
  }

  private CoachStep decide() {
    coach.step = coach.decide();
    return coach.step;
  }

  private void expect(CoachStep.Kind kind, int patch) {
    CoachStep step = decide();
    assertNotNull(step);
    assertEquals(kind, step.kind);
    assertEquals(patch < 0 ? null : patches.get(patch), step.target);
  }

  private void change(int index, PlantState state) {
    coach.updatePlot(patches.get(index), null, state, now);
  }

  private void plantBatch() {
    for (int i = 0; i < coach.route.size(); i++) {
      change(i, PlantState.DRY);
      change(i, PlantState.WATERED);
    }
  }

  private void finishBatch() {
    plantBatch();
    expect(CoachStep.Kind.WAIT, 0);
    for (int i = 0; i < coach.route.size(); i++) {
      change(i, PlantState.GROWN);
      expect(CoachStep.Kind.HARVEST, i);
      change(i, PlantState.EMPTY);
    }
  }

  private void supplies(int water, int fruit) {
    coach.inventory =
        new TitheInventory(
            new Item[] {
              new Item(ItemID.ZEAH_WATERINGCAN, 1),
              new Item(ItemID.HOSIDIUS_TITHE_SEED_A, 100),
              new Item(ItemID.HOSIDIUS_TITHE_FRUIT_A, fruit)
            },
            water);
  }
}

package com.galesong.tithecoach;

import static org.junit.Assert.*;

import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class TitheInventoryTest {
  @Test
  public void sumsRegularCanDosesAndChoosesTheFullestCan() {
    TitheInventory inventory =
        new TitheInventory(
            new Item[] {new Item(ItemID.WATERING_CAN_8, 2), new Item(ItemID.WATERING_CAN_3, 1)},
            999);
    assertEquals(19, inventory.waterDoseCount());
    assertEquals(ItemID.WATERING_CAN_8, inventory.firstWateringCan());
  }

  @Test
  public void gricollersCanTakesPrecedenceOverRegularCansEvenWhenEmpty() {
    Item[] items = {new Item(ItemID.ZEAH_WATERINGCAN, 1), new Item(ItemID.WATERING_CAN_8, 1)};
    assertEquals(17, new TitheInventory(items, 17).waterDoseCount());
    assertEquals(0, new TitheInventory(items, -1).waterDoseCount());
    assertEquals(ItemID.ZEAH_WATERINGCAN, new TitheInventory(items, 0).firstWateringCan());
  }

  @Test
  public void selectsHighestSeedAndFruitTierWhileCountingAllFruit() {
    TitheInventory inventory =
        new TitheInventory(
            new Item[] {
              new Item(ItemID.HOSIDIUS_TITHE_SEED_A, 100),
              new Item(ItemID.HOSIDIUS_TITHE_SEED_C, 100),
              new Item(ItemID.HOSIDIUS_TITHE_FRUIT_A, 7),
              new Item(ItemID.HOSIDIUS_TITHE_FRUIT_B, 2)
            },
            0);
    assertEquals(ItemID.HOSIDIUS_TITHE_SEED_C, inventory.seedId());
    assertEquals(ItemID.HOSIDIUS_TITHE_FRUIT_B, inventory.fruitId());
    assertEquals(9, inventory.fruitCount());
    assertEquals(-1, new TitheInventory(null, 0).seedId());
    assertEquals(0, new TitheInventory(null, 0).waterDoseCount());
  }
}

